import dados from "./vsl4-dados.json";

// Renan Boucault v2: a VSL dele editada de verdade. Pausas cortadas, zoom alternado a cada frase, legenda palavra a palavra,
// letterings nos pontos-chave da fala, fotos discretas, depoimento e chamada final, sobre trilha calma.
// Tudo do peito para baixo: o rosto dele fica sempre livre.

const { fontFamily: sans } = loadSans("normal", { weights: ["400", "500", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: serif } = loadSerif("italic", { subsets: ["latin", "latin-ext"] });

export const RENAN5_FPS = 30;
const f = (seg: number) => Math.round(seg * RENAN5_FPS);
export const RENAN5_FRAMES = f(dados.total);
const GOLD = "#C0A16B";
const CREME = "#F2EEE6";
const asset = (n: string) => staticFile(`renan/${n}`);

type Bloco = { fonte: string; de: number; ate: number; saida: number };
const BLOCOS = dados.blocos as Bloco[];

// tempo da VSL original → tempo do vídeo editado
const m = (src: number) => {
  for (const b of BLOCOS) if (b.fonte === "vsl" && src >= b.de - 1e-6 && src <= b.ate + 1e-6) return b.saida + src - b.de;
  for (const b of BLOCOS) if (b.fonte === "vsl" && b.de >= src) return b.saida;
  return dados.total;
};

