const ZONA = 1150; // v5: enquadramento dele sobe 260 px; cartões abaixo do queixo e dentro da área segura (até 1480)
const SEGURO = 1480;

// ---------------------------------------------------------------- peças
const useEntrada = (atraso = 0, dur?: number) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const e = spring({ frame: frame - atraso, fps, config: { damping: 22, stiffness: 170 }, durationInFrames: 14 });
  const sai = dur ? interpolate(frame, [dur - 9, dur - 2], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.cubic) }) : 0;
  return { e, sai };
};

// texto entra por máscara, de baixo, e fica parado; sai pela máscara para cima
const Linha: React.FC<{ altura: number; atraso?: number; dur: number; children: React.ReactNode }> = ({ altura, atraso = 0, dur, children }) => {
  const { e, sai } = useEntrada(atraso, dur);
  return (
    <div style={{ height: altura, overflow: "hidden", display: "flex", justifyContent: "center" }}>
      <div style={{ transform: `translateY(${(1 - e) * altura * 1.05 - sai * altura * 1.05}px)`, whiteSpace: "nowrap", lineHeight: `${altura}px` }}>{children}</div>
    </div>
  );
};

const Fio: React.FC<{ atraso?: number; dur: number; largura: number }> = ({ atraso = 0, dur, largura }) => {
  const frame = useCurrentFrame();
  const w = interpolate(frame - atraso, [0, 12], [0, largura], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) });
  const sai = interpolate(frame, [dur - 9, dur - 2], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return <div style={{ width: w * sai, height: 3, background: GOLD, margin: "0 auto", boxShadow: `0 0 12px ${GOLD}88` }} />;
};

// cartão escuro atrás do lettering (a camisa listrada come o contraste); abre do centro para os lados e fecha no fim
const Bloco: React.FC<{ dur: number; children: React.ReactNode }> = ({ dur, children }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const abre = spring({ frame, fps, config: { damping: 24, stiffness: 160 }, durationInFrames: 12 });
  const fecha = interpolate(frame, [dur - 7, dur], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.cubic) });
  const lado = (1 - abre * (1 - fecha)) * 50;
  return (
    <div style={{ position: "absolute", top: ZONA, left: 120, right: 120, height: SEGURO - ZONA, display: "flex", justifyContent: "center", alignItems: "flex-start" }}>
      <div style={{ position: "relative", padding: "20px 44px" }}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: "rgba(8,8,8,0.74)",
            border: `1.5px solid ${GOLD}66`,
            borderRadius: 24,
            boxShadow: "0 20px 60px rgba(0,0,0,0.45)",
            clipPath: `inset(0 ${lado}% 0 ${lado}% round 24px)`,
          }}
        />
        <div style={{ position: "relative", display: "flex", flexDirection: "column", alignItems: "center" }}>{children}</div>
      </div>
    </div>
  );
};

const Vontade: React.FC<{ dur: number }> = ({ dur }) => (
  <Bloco dur={dur}>
