const Lista: React.FC<{ dur: number; ini: number }> = ({ dur, ini }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const sai = interpolate(frame, [dur - 9, dur - 2], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <div style={{ position: "absolute", top: ZONA + 5, left: 120, right: 120, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, opacity: 1 - sai }}>
      {LISTA.map((it) => {
        const at = f(m(it.src)) - ini;
        const e = spring({ frame: frame - at, fps, config: { damping: 16, stiffness: 200 }, durationInFrames: 12 });
        return (
          <div key={it.t} style={{ height: 86, borderRadius: 14, overflow: "hidden" }}>
            <div
              style={{
                height: "100%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                background: "rgba(10,10,10,0.82)",
                border: `2px solid ${GOLD}`,
                borderRadius: 14,
                transform: `translateY(${(1 - e) * 110}px)`,
