            >
              {it.t}
            </div>
          </div>
        );
      })}
      {LISTA.map((it, i) => (
        <Sequence key={`s${i}`} from={f(m(it.src)) - ini} durationInFrames={30}>
          <Audio src={asset(`p${i + 1}.wav`)} volume={0.22} />
