const FotoCard: React.FC<{ it: Foto; dur: number }> = ({ it, dur }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const FH = SEGURO - ZONA - 20 - 16 - 64 - 30; // altura livre para a foto (com folga de 30 px)
  const k = Math.min(840 / it.w, FH / it.h);
  const w = Math.round(it.w * k);
  const h = Math.round(it.h * k);
  const top = ZONA + 10;
  const abre = spring({ frame, fps, config: { damping: 22, stiffness: 150 }, durationInFrames: 12 });
  const fecha = interpolate(frame, [dur - 9, dur], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.cubic) });
  const aberto = abre * (1 - fecha);
  const lado = ((1 - aberto) * w) / 2;
  const linha = interpolate(aberto, [0, 0.9, 1], [1, 1, 0]);
  const push = interpolate(frame, [0, dur], [1.07, 1.0]);
  return (
    <AbsoluteFill>
      <div style={{ position: "absolute", left: (1080 - w) / 2, top, width: w, height: h }}>
        <div style={{ position: "absolute", inset: 0, overflow: "hidden", clipPath: `inset(0 ${lado}px 0 ${lado}px)`, boxShadow: "0 24px 60px rgba(0,0,0,0.6)" }}>
          <Img src={asset(it.foto)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${push})` }} />
          <div style={{ position: "absolute", inset: 0, border: `2px solid ${GOLD}` }} />
        </div>
        <div style={{ position: "absolute", left: w / 2 - 1.5, top: 0, width: 3, height: h, background: GOLD, opacity: linha, boxShadow: `0 0 14px ${GOLD}` }} />
      </div>
      <div style={{ position: "absolute", top: ZONA + 10 + h + 16, left: 0, right: 0 }}>
        <Linha altura={64} atraso={6} dur={dur}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 18, padding: "0 30px", background: "rgba(0,0,0,0.78)", borderRadius: 6 }}>
            <span style={{ fontFamily: serif, fontStyle: "italic", fontSize: 44, color: GOLD }}>{it.titulo}</span>
            {it.sub && (
              <>
                <span style={{ width: 7, height: 7, borderRadius: 4, background: GOLD }} />
                <span style={{ fontFamily: sans, fontWeight: 500, fontSize: 28, color: CREME, letterSpacing: 1 }}>{it.sub}</span>
              </>
            )}
          </span>
        </Linha>
      </div>
    </AbsoluteFill>
  );
};

