// ---------------------------------------------------------------- cenas desenhadas (v3)
type Cena = React.FC<{ dur: number; ini: number }>;
// quadro (relativo ao começo da cena) em que ele fala a palavra do tempo `src` da VSL original
const q = (src: number, ini: number) => f(m(src)) - ini;
const desenha = (frame: number, de: number, dur: number) =>
  interpolate(frame, [de, de + dur], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) });

// abertura: barra de busca digitando "hipnose", como quem chegou pesquisando
const Busca: Cena = ({ dur, ini }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const palavra = "hipnose";
  const t0 = q(1.45, ini);
  const t1 = q(2.85, ini);
  const n = Math.floor(interpolate(frame, [t0, t1], [0, palavra.length], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }));
  const cursor = Math.floor(frame / 8) % 2 === 0;
  const res = q(2.6, ini);
  return (
    <Bloco dur={dur}>
      <div style={{ width: 720, height: 112, borderRadius: 56, background: CREME, display: "flex", alignItems: "center", padding: "0 40px", gap: 26 }}>
        <svg width="54" height="54" viewBox="0 0 54 54">
          <circle cx="22" cy="22" r="15" fill="none" stroke="#1a1a1a" strokeWidth="5" />
          <path d="M33 33 L48 48" stroke="#1a1a1a" strokeWidth="6" strokeLinecap="round" />
        </svg>
        <span style={{ fontFamily: sans, fontWeight: 500, fontSize: 52, color: n ? "#111" : "#8a8580" }}>
          {n ? palavra.slice(0, n) : "Pesquisar"}
          <span style={{ display: "inline-block", width: 4, height: 54, background: GOLD, marginLeft: 6, verticalAlign: "middle", opacity: cursor ? 1 : 0 }} />
        </span>
      </div>
      <div style={{ height: 30 }} />
      {[0, 1, 2].map((i) => {
        const e = spring({ frame: frame - res - i * 4, fps, config: { damping: 20, stiffness: 180 }, durationInFrames: 12 });
        return <div key={i} style={{ width: [620, 520, 580][i], height: 22, borderRadius: 11, background: i === 0 ? GOLD : "rgba(242,238,230,0.35)", margin: "10px 0", transform: `scaleX(${e})`, transformOrigin: "left", alignSelf: "flex-start", marginLeft: 50 }} />;
      })}
      {<Sequence from={t0} durationInFrames={50}><Audio src={asset("digita.wav")} volume={0.35} /></Sequence>}
    </Bloco>
  );
};

// "tentando resolver um problema seu, mas não está conseguindo": a barra enche e volta ao zero
const Progresso: Cena = ({ dur, ini }) => {
  const frame = useCurrentFrame();
  const cai = q(6.23, ini);
  const sobe = interpolate(frame, [4, cai], [0, 0.82], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.quad) });
  const desce = interpolate(frame, [cai, cai + 10], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.cubic) });
  const v = sobe * (1 - desce * 0.94);
  return (
    <Bloco dur={dur}>
      <Linha altura={64} dur={dur}>
        <span style={{ fontFamily: sans, fontWeight: 500, fontSize: 46, color: CREME }}>Tentando resolver…</span>
      </Linha>
      <div style={{ height: 26 }} />
      <div style={{ width: 680, height: 34, borderRadius: 17, background: "rgba(242,238,230,0.15)", overflow: "hidden" }}>
        <div style={{ width: `${v * 100}%`, height: "100%", borderRadius: 17, background: desce > 0 ? "#8C7550" : GOLD, boxShadow: `0 0 18px ${GOLD}66` }} />
      </div>
      <div style={{ height: 18 }} />
      <span style={{ fontFamily: serif, fontStyle: "italic", fontSize: 76, color: GOLD, fontVariantNumeric: "tabular-nums", lineHeight: "84px" }}>{Math.round(v * 100)}%</span>
      <Sequence from={cai}><Audio src={asset("gl.wav")} volume={0.18} /></Sequence>
    </Bloco>
  );
};

// "prometido para si mesmo que dessa vez ia ser diferente": um bilhete, palavra a palavra
const Promessa: Cena = ({ dur, ini }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const e = spring({ frame, fps, config: { damping: 18, stiffness: 140 }, durationInFrames: 16 });
  const fecha = interpolate(frame, [dur - 8, dur], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const palavras = [
    { t: "“Dessa", s: 9.84 },
    { t: "vez", s: 10.18 },
    { t: "vai", s: 10.38 },
    { t: "ser", s: 10.51 },
    { t: "diferente.”", s: 10.71 },
  ];
  return (
    <div style={{ position: "absolute", top: ZONA + 6, left: 0, right: 0, display: "flex", justifyContent: "center" }}>
      <div
        style={{
          width: 760,
          padding: "22px 46px 24px",
          background: CREME,
          borderRadius: 10,
          boxShadow: "0 30px 70px rgba(0,0,0,0.55)",
          transform: `translateY(${(1 - e) * 30 + fecha * 30}px) rotate(${-2.5 + (1 - e) * 4}deg)`,
          clipPath: `inset(0 ${(1 - e * (1 - fecha)) * 50}% 0 ${(1 - e * (1 - fecha)) * 50}% round 10px)`,
          borderTop: `12px solid ${GOLD}`,
