// ---------------------------------------------------------------- legenda palavra a palavra
type Palavra = { t: string; a: number; b: number; src: number };
const PALAVRAS = (dados.palavras as Palavra[]).filter((p) => p.src < 87.55 || p.src >= 87.55);
const GRUPOS: Palavra[][] = (() => {
  const g: Palavra[][] = [];
  let cur: Palavra[] = [];
  for (const p of PALAVRAS) {
    cur.push(p);
    const chars = cur.map((x) => x.t).join(" ").length;
    if (/[.,!?]$/.test(p.t) || cur.length >= 3 || chars > 16) {
      g.push(cur);
      cur = [];
    }
  }
  if (cur.length) g.push(cur);
  return g;
})();

const ocupado = (t: number) => MOMENTOS.some((mo) => t >= m(mo.de) - 0.05 && t < m(mo.ate) + 0.1) || (t >= dados.depIni - 0.2 && t < dados.depFim + 0.3);

const Legenda: React.FC = () => {
  const frame = useCurrentFrame();
  const t = frame / RENAN5_FPS;
  if (ocupado(t)) return null;
  const gi = GRUPOS.findIndex((g, i) => t >= g[0].a - 0.05 && t < (GRUPOS[i + 1]?.[0].a ?? g[g.length - 1].b + 0.6) - 0.05);
  if (gi < 0) return null;
  const g = GRUPOS[gi];
  if (t > g[g.length - 1].b + 0.8) return null;
  const desde = frame - f(g[0].a - 0.05);
  const e = interpolate(desde, [0, 5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) });
  return (
    <div style={{ position: "absolute", top: 1350, left: 120, right: 120, height: 110, overflow: "hidden", display: "flex", justifyContent: "center", alignItems: "center" }}>
      <div style={{ transform: `translateY(${(1 - e) * 60}px)`, opacity: e, whiteSpace: "nowrap", fontFamily: sans, fontWeight: 700, fontSize: 64, textShadow: "0 4px 18px rgba(0,0,0,0.75), 0 0 2px rgba(0,0,0,0.9)" }}>
        {g.map((p, i) => {
          const dita = t >= p.a - 0.03;
          return (
            <span key={i} style={{ color: dita ? (t < p.b + 0.05 ? GOLD : CREME) : "rgba(242,238,230,0.55)" }}>
              {p.t.replace(/[.,]$/, "")}
              {i < g.length - 1 ? " " : ""}
            </span>
          );
        })}
      </div>
    </div>
  );
};

// ---------------------------------------------------------------- vídeo dele com zoom por frase
const FRASES = dados.frases as number[];
// trocas de enquadramento: cada frase e cada cena que entra por cima
const TROCAS = Array.from(new Set([...FRASES, ...MOMENTOS.map((mo) => m(mo.de))].map((x) => Math.round(x * 10) / 10))).sort((a, b) => a - b);
const NIVEIS = [1.2, 1.26, 1.23, 1.29]; // v5: com o vídeo 260 px acima, 1,2 é o mínimo para não sobrar faixa embaixo
const Ele: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / RENAN5_FPS;
  let i = 0;
  for (let k = 0; k < TROCAS.length; k++) if (t >= TROCAS[k] - 0.02) i = k;
  const ini = TROCAS[i] ?? 0;
  const ant = NIVEIS[(i + NIVEIS.length - 1) % NIVEIS.length];
  const alvo = NIVEIS[i % NIVEIS.length];
  // troca rápida com impulso (6 quadros), depois aproximação lenta dentro da frase
  const s = spring({ frame: frame - f(ini), fps, config: { damping: 20, stiffness: 260 }, durationInFrames: 7 });
  const lento = interpolate(t - ini, [0, 6], [0, 0.02], { extrapolateRight: "clamp" });
  // abertura: entra de bem perto e abre
  const intro = interpolate(spring({ frame, fps, config: { damping: 18, stiffness: 90 }, durationInFrames: 22 }), [0, 1], [0.4, 0]);
  const esc = (i === 0 ? alvo : ant + (alvo - ant) * s) + lento + intro;
  return (
    <AbsoluteFill style={{ transform: `translateY(-260px) scale(${esc})`, transformOrigin: "50% 30%" }}>
      {BLOCOS.filter((b) => b.fonte === "vsl").map((b) => (
        <Sequence key={b.saida} from={f(b.saida)} durationInFrames={f(b.saida + b.ate - b.de) - f(b.saida)} premountFor={30}>
