const TROCA_PACIENTE = 22.28;
const VEL_DEP = 1.2; // depoimento-12.mp4: acelerado 1,2x (pedido do Renan)

const Depoimento: React.FC<{ dur: number }> = ({ dur }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const SQ = 840; // v5: dentro da margem de 120 px (a arte das pacientes tem texto até a borda)
  const TIT = 110;
  const ROD = 96;
  const topo = 1480 - (TIT + 40 + SQ + 44 + ROD) - 30; // tudo entre 250 e 1480
  const depBlocos = BLOCOS.filter((b) => b.fonte === "dep");
  // quadro desta sequência em que o depoimento original está no tempo `src`
  const qd = (orig: number) => {
    const src = orig / VEL_DEP;
    for (const b of depBlocos) if (src >= b.de - 1e-6 && src <= b.ate + 1e-6) return f(b.saida + src - b.de) - f(dados.depIni) + 8;
    for (const b of depBlocos) if (b.de >= src) return f(b.saida) - f(dados.depIni) + 8;
    return dur;
  };
  const abre = spring({ frame, fps, config: { damping: 24, stiffness: 120 }, durationInFrames: 16 });
  const fecha = interpolate(frame, [dur - 12, dur], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.cubic) });
  const aberto = abre * (1 - fecha);
  const v = ((1 - aberto) * SQ) / 2;
  const linha = interpolate(aberto, [0, 0.9, 1], [1, 1, 0]);
  const fundo = interpolate(frame, [0, 8, dur - 8, dur], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  // zoom lento em cada paciente; na troca, o fio dourado varre o quadro
  const tp = qd(TROCA_PACIENTE);
  const zoom = 1; // v4: sem zoom, cortava palavras da legenda delas
  const varre = interpolate(frame, [tp - 6, tp + 6], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) });
  const varreOn = frame >= tp - 6 && frame <= tp + 8;
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, #1c1c1c 0%, #0a0a0a 60%, #000 100%)", opacity: fundo }} />
      <div style={{ position: "absolute", top: topo, left: 0, right: 0 }}>
        <Linha altura={TIT} atraso={6} dur={dur}>
          <span style={{ fontFamily: serif, fontStyle: "italic", fontSize: 92, color: GOLD }}>Relatos reais</span>
        </Linha>
      </div>
      <div style={{ position: "absolute", left: (1080 - SQ) / 2, top: topo + TIT + 40, width: SQ, height: SQ }}>
        <div style={{ position: "absolute", inset: 0, overflow: "hidden", clipPath: `inset(${v}px 0 ${v}px 0)` }}>
          <AbsoluteFill style={{ transform: `scale(${zoom})`, transformOrigin: "50% 45%" }}>
            {depBlocos.map((b) => (
              <Sequence key={b.saida} from={f(b.saida) - f(dados.depIni) + 8} durationInFrames={f(b.saida + b.ate - b.de) - f(b.saida)} premountFor={30}>
                <OffthreadVideo src={asset("depoimento-12.mp4")} trimBefore={f(b.de)} style={{ width: SQ, height: SQ }} />
              </Sequence>
            ))}
          </AbsoluteFill>
          {varreOn && <div style={{ position: "absolute", left: 0, right: 0, top: varre * SQ - 2, height: 4, background: GOLD, boxShadow: `0 0 24px ${GOLD}` }} />}
          <div style={{ position: "absolute", inset: 0, border: `2px solid ${GOLD}` }} />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: SQ / 2 - 1.5, height: 3, background: GOLD, opacity: linha, boxShadow: `0 0 16px ${GOLD}` }} />
      </div>
      {FALAS.map((fa, i) => {
        const de = Math.max(qd(fa.s), 14);
        const ate = i < FALAS.length - 1 ? qd(FALAS[i + 1].s) : dur - 4;
        return (
          <Sequence key={fa.t} from={de} durationInFrames={ate - de}>
            <div style={{ position: "absolute", top: topo + TIT + 40 + SQ + 44, left: 0, right: 0 }}>
              <Linha altura={ROD} dur={ate - de}>
                <span style={{ display: "inline-flex", alignItems: "center", gap: 20, padding: "0 36px", height: ROD, border: `2px solid ${GOLD}`, borderRadius: 48, background: "rgba(192,161,107,0.12)" }}>
                  <span style={{ width: 10, height: 10, borderRadius: 5, background: GOLD }} />
                  <span style={{ fontFamily: serif, fontStyle: "italic", fontSize: 54, color: CREME }}>{fa.t}</span>
                </span>
              </Linha>
            </div>
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};

