        const dur = f(m(mo.ate)) - ini;
        const P = PECAS[mo.id];
        const foto = FOTOS[mo.id];
        return (
          <Sequence key={mo.id} from={ini} durationInFrames={dur}>
            {P ? <P dur={dur} ini={ini} /> : foto ? <FotoCard it={foto} dur={dur} /> : null}
            {som && mo.som && <Audio src={asset(mo.som)} volume={mo.vol ?? 0.2} />}
          </Sequence>
        );
      })}
      <Sequence from={depIni - 8} durationInFrames={depDur + 16}>
        <Depoimento dur={depDur + 16} />
        {som && <Audio src={asset("elegant.wav")} volume={0.18} />}
      </Sequence>
      <Sequence from={depIni + depDur - 6} durationInFrames={45}>
        {som && <Audio src={asset("o6.wav")} volume={0.2} />}
      </Sequence>
      {som && <Audio src={asset("trilha.wav")} volume={(fr) => trilhaVol(fr / RENAN5_FPS)} />}
    </AbsoluteFill>
  );
};

// trilha bem abaixo da voz; abaixa mais no depoimento (o vídeo das pacientes já tem som próprio)
const trilhaVol = (t: number) => {
  const base = 0.18; // v4: música um pouco mais baixa
  const dep = interpolate(t, [dados.depIni - 0.3, dados.depIni + 0.5, dados.depFim - 0.5, dados.depFim + 0.3], [1, 0.45, 0.45, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const fim = interpolate(t, [dados.total - 2, dados.total], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return base * dep * fim;
};

